def reverse_in_place(values):
 left=0;right=len(values)-1
 while left<right:values[left],values[right]=values[right],values[left];left+=1;right-=1
def reverse_copy(values):return [values[index]for index in range(len(values)-1,-1,-1)]
class Backwards:
 def __init__(self,values):self.values=values;self.index=len(values)
 def __iter__(self):return self
 def __next__(self):
  if not self.index:raise StopIteration
  self.index-=1;return self.values[self.index]
def reverse_iterator(values):return Backwards(values)
